import json,collections
OUT=__import__('os').path.join(__import__('os').path.dirname(__import__('os').path.abspath(__file__)),'..','..')+'/'
R=json.load(open('reqs.json'))
by=collections.defaultdict(list)
for r in R: by[r['phase']].append(r)
def reqs(p): return ', '.join(r['id']+(' (C '+r['cond']+')' if r['cond'] else '') for r in by[p]) or 'none'
def tests(p): return ', '.join(t for r in by[p] for t in r['tids'])
def scen(p): return ', '.join((f"S-013-1..{len(r['sids'])}" if r['id']=='REQ-013' else ', '.join(s for s in r['sids'] if s)) for r in by[p] if any(r['sids'])) or 'none'
